class Solution:
    def largestNumber(self, cost: List[int], target: int) -> str:
        NEG = float('-inf')
        memo = {0: 0}
        def f(c):
            if c in memo:
                return memo[c]
            best = NEG
            for i in range(9):
                if cost[i] <= c:
                    best = max(best, f(c - cost[i]) + 1)
            memo[c] = best
            return best
        total = f(target)
        if total <= 0:
            return "0"
        res = []
        rem = target
        while rem > 0:
            for d in range(9, 0, -1):
                if cost[d - 1] <= rem and f(rem - cost[d - 1]) == f(rem) - 1:
                    res.append(str(d))
                    rem -= cost[d - 1]
                    break
        return "".join(res)

