class Solution {
public:
    vector<int> memo;
    vector<int> cst;
    int f(int c) {
        if (c == 0) return 0;
        int &r = memo[c];
        if (r != INT_MIN) return r;
        r = INT_MIN + 1;
        for (int i = 0; i < 9; i++)
            if (cst[i] <= c) {
                int sub = f(c - cst[i]);
                if (sub >= 0) r = max(r, sub + 1);
            }
        return r;
    }
    string largestNumber(vector<int>& cost, int target) {
        cst = cost;
        memo.assign(target + 1, INT_MIN);
        int total = f(target);
        if (total <= 0) return "0";
        string res;
        int rem = target;
        while (rem > 0) {
            for (int d = 9; d >= 1; d--) {
                if (cost[d - 1] <= rem && f(rem - cost[d - 1]) == f(rem) - 1) {
                    res += ('0' + d);
                    rem -= cost[d - 1];
                    break;
                }
            }
        }
        return res;
    }
};

