class Solution {
    private int[] memo, cost;
    private int f(int c) {
        if (c == 0) return 0;
        if (memo[c] != Integer.MIN_VALUE) return memo[c];
        int best = Integer.MIN_VALUE + 1;
        for (int i = 0; i < 9; i++) {
            if (cost[i] <= c) {
                int sub = f(c - cost[i]);
                if (sub >= 0) best = Math.max(best, sub + 1);
            }
        }
        return memo[c] = best;
    }
    public String largestNumber(int[] cost, int target) {
        this.cost = cost;
        memo = new int[target + 1];
        Arrays.fill(memo, Integer.MIN_VALUE);
        int total = f(target);
        if (total <= 0) return "0";
        StringBuilder sb = new StringBuilder();
        int rem = target;
        while (rem > 0) {
            for (int d = 9; d >= 1; d--) {
                if (cost[d - 1] <= rem && f(rem - cost[d - 1]) == f(rem) - 1) {
                    sb.append(d);
                    rem -= cost[d - 1];
                    break;
                }
            }
        }
        return sb.toString();
    }
}

